INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('fd0ff1dd-4856-4f51-b2a8-d914ed6a4d19', '051b209e-9985-44da-a832-ca884783cb98', 1, 'A Vontade Adormecida', NULL, '{"intro": "Psicologicamente, a vontade fraca \u00e9 fruto de decis\u00f5es adiadas.", "prayer": "Identifique uma \u00e1rea de pregui\u00e7a e a enfrente.", "practice": "Tome uma pequena decis\u00e3o hoje e cumpra-a imediatamente.", "reflection": "O maior inimigo da virtude n\u00e3o \u00e9 o erro, \u00e9 a in\u00e9rcia.", "journal_prompt": "O que voc\u00ea est\u00e1 evitando decidir?"}'), ('d6c3dab7-7d22-4195-92f3-472f6de6bc16', '051b209e-9985-44da-a832-ca884783cb98', 2, 'O Ordenamento dos Afetos', NULL, '{"intro": "Desordem emocional gera ansiedade constante.", "prayer": "Ore pedindo a gra\u00e7a de amar o que \u00e9 eterno.", "practice": "Escolha um objeto em sua casa e o organize conscientemente.", "reflection": "Amar \u00e9 colocar as coisas no seu devido lugar.", "journal_prompt": "Seus amores est\u00e3o em ordem?"}'), ('f9ed5e91-2888-4f7e-8499-85f71ffe2101', '051b209e-9985-44da-a832-ca884783cb98', 3, 'A Força do Hábito', NULL, '{"intro": "H\u00e1bitos s\u00e3o os trilhos sobre os quais nossa vida corre.", "prayer": "Pe\u00e7a const\u00e2ncia para as pequenas coisas.", "practice": "Inicie hoje um novo micro-h\u00e1bito positivo.", "reflection": "Somos o que fazemos repetidamente.", "journal_prompt": "Quais trilhos voc\u00ea est\u00e1 construindo hoje?"}'), ('8c2ff870-c484-4716-b31b-cf4d3ed019e5', '051b209e-9985-44da-a832-ca884783cb98', 4, 'O Silêncio Educativo', NULL, '{"intro": "Falar demais \u00e9 uma fuga do encontro consigo mesmo.", "prayer": "No sil\u00eancio, escute os batimentos do seu cora\u00e7\u00e3o.", "practice": "Fique 30 minutos sem falar nada, apenas observando.", "reflection": "Quem n\u00e3o domina a pr\u00f3pria l\u00edngua n\u00e3o domina a si mesmo.", "journal_prompt": "O que o seu barulho tenta esconder?"}'), ('5faa51eb-e635-4b43-bd47-627c5fa2efcf', '051b209e-9985-44da-a832-ca884783cb98', 5, 'A Obediência à Verdade', NULL, '{"intro": "Negar a realidade \u00e9 a raiz de todo sofrimento ps\u00edquico.", "prayer": "Abrace a sua fragilidade diante do Infinito.", "practice": "Aceite uma verdade dif\u00edcil sobre voc\u00ea hoje.", "reflection": "A liberdade real nasce de submeter-se ao que \u00e9 verdadeiro.", "journal_prompt": "Voc\u00ea prefere a mentira que conforta ou a verdade que cura?"}'), ('93c7e138-b527-4d3d-962e-df7b7447184a', '051b209e-9985-44da-a832-ca884783cb98', 6, 'A Coragem do Não', NULL, '{"intro": "A incapacidade de dizer n\u00e3o \u00e9 falta de identidade.", "prayer": "Pe\u00e7a for\u00e7a para sustentar suas escolhas.", "practice": "Diga n\u00e3o a algo que rouba o seu tempo hoje.", "reflection": "Dizer sim a tudo \u00e9 dizer n\u00e3o a si mesmo.", "journal_prompt": "A quem voc\u00ea est\u00e1 tentando agradar?"}'), ('7c57cc31-4852-4427-b2d7-02a25e3de1a5', '051b209e-9985-44da-a832-ca884783cb98', 7, 'O Caráter que se Ergue', NULL, '{"intro": "O homem formado \u00e9 aquele que se torna porto seguro para os outros.", "prayer": "Agrade\u00e7a pela jornada de fortalecimento.", "practice": "Fa\u00e7a algo por algu\u00e9m sem esperar nada em troca.", "reflection": "A forma\u00e7\u00e3o termina quando a sua vida se torna um dom.", "journal_prompt": "Quem pode contar com voc\u00ea hoje?"}'), ('182be334-906b-447c-8bb7-7be26c2ed328', '0b8ddab7-b106-4873-bc4d-3987421d265d', 1, 'O Despertar Sagrado', NULL, '{"intro": "O primeiro pensamento do dia \u00e9 a semente de todas as suas a\u00e7\u00f5es.", "prayer": "Ofere\u00e7a o seu dia antes de sair da cama.", "practice": "N\u00e3o pegue no celular nos primeiros 15 minutos do dia.", "reflection": "A forma como voc\u00ea come\u00e7a o dia determina a sua alma.", "journal_prompt": "Qual \u00e9 a primeira coisa que voc\u00ea entrega ao mundo ao acordar?"}'), ('57763fc6-f48e-436d-a54f-f3431216a562', '0b8ddab7-b106-4873-bc4d-3987421d265d', 2, 'O Dever do Momento', NULL, '{"intro": "A ansiedade nasce de querer estar no futuro e negligenciar o presente.", "prayer": "Pe\u00e7a a gra\u00e7a da presen\u00e7a de esp\u00edrito.", "practice": "Fa\u00e7a a sua tarefa mais chata com total aten\u00e7\u00e3o e amor.", "reflection": "A santidade est\u00e1 em fazer bem o que se deve fazer agora.", "journal_prompt": "Voc\u00ea est\u00e1 presente no que est\u00e1 fazendo?"}'), ('99ec6d50-4d70-4e62-9da8-e7ddcc40d68d', '0b8ddab7-b106-4873-bc4d-3987421d265d', 3, 'As Pequenas Mortes', NULL, '{"intro": "Pequenos sacrif\u00edcios fortalecem a alma contra grandes quedas.", "prayer": "Ofere\u00e7a essa pequena morte pela convers\u00e3o de algu\u00e9m.", "practice": "Renuncie a uma pequena satisfa\u00e7\u00e3o hoje (um caf\u00e9, um doce, um coment\u00e1rio).", "reflection": "Cada ren\u00fancia \u00e9 um espa\u00e7o que se abre para a vida.", "journal_prompt": "O que voc\u00ea pode soltar para ser mais livre?"}'), ('690f82c8-60c1-4876-81ea-db828cbb8172', '0b8ddab7-b106-4873-bc4d-3987421d265d', 4, 'A Alimentação da Alma', NULL, '{"intro": "O que voc\u00ea l\u00ea, assiste e ouve molda a sua percep\u00e7\u00e3o da realidade.", "prayer": "Pe\u00e7a discernimento para o que voc\u00ea deixa entrar pelos olhos.", "practice": "Leia 5 p\u00e1ginas de um livro espiritual em vez de rolar as redes sociais.", "reflection": "Voc\u00ea se torna o que voc\u00ea consome.", "journal_prompt": "Como est\u00e1 a sa\u00fade da sua alma hoje?"}'), ('995d2b5f-1b4c-4a45-a32b-4454c650afc2', '0b8ddab7-b106-4873-bc4d-3987421d265d', 5, 'O Encontro no Meio do Dia', NULL, '{"intro": "A rotina nos engole se n\u00e3o criarmos ilhas de sil\u00eancio.", "prayer": "Recite o Angelus ou uma ora\u00e7\u00e3o curta de entrega.", "practice": "Pare tudo por 2 minutos ao meio-dia para uma ora\u00e7\u00e3o r\u00e1pida.", "reflection": "Uma pausa para respirar \u00e9 uma pausa para lembrar de Deus.", "journal_prompt": "Voc\u00ea se lembrou dEle hoje?"}'), ('49208096-da61-4368-9311-7f68034f6a7e', '0b8ddab7-b106-4873-bc4d-3987421d265d', 6, 'A Caridade Ordinária', NULL, '{"intro": "O amor se prova na paci\u00eancia com quem est\u00e1 ao nosso lado.", "prayer": "Pe\u00e7a para ver Cristo no pr\u00f3ximo.", "practice": "Fa\u00e7a um elogio sincero a algu\u00e9m que convive com voc\u00ea.", "reflection": "N\u00e3o espere grandes ocasi\u00f5es para amar.", "journal_prompt": "Quem voc\u00ea amou hoje de forma concreta?"}'), ('d71cbf89-8f87-414f-8eeb-675a3959172a', '0b8ddab7-b106-4873-bc4d-3987421d265d', 7, 'O Exame da Noite', NULL, '{"intro": "O fim do dia \u00e9 o tempo da colheita e do perd\u00e3o.", "prayer": "Pe\u00e7a perd\u00e3o pelas falhas e agrade\u00e7a pelas vit\u00f3rias.", "practice": "Reveja o seu dia antes de dormir: onde houve amor? Onde faltou?", "reflection": "Ningu\u00e9m melhora o que n\u00e3o avalia.", "journal_prompt": "Se hoje fosse o seu \u00faltimo dia, voc\u00ea estaria em paz?"}'), ('12bea220-594b-4e61-952f-98f4fdca8436', '150f78d3-019b-40c0-962e-a83576309ea5', 1, 'O Centro de Gravidade', NULL, '{"intro": "O cora\u00e7\u00e3o \u00e9 o centro de comando de todas as nossas decis\u00f5es.", "prayer": "Pe\u00e7a para ancorar seu cora\u00e7\u00e3o na Verdade.", "practice": "Observe para onde o seu pensamento foge quando voc\u00ea est\u00e1 livre.", "reflection": "Onde est\u00e1 o teu tesouro, a\u00ed estar\u00e1 o teu cora\u00e7\u00e3o.", "journal_prompt": "O que ocupa o trono do seu cora\u00e7\u00e3o hoje?"}'), ('62d23419-0510-4f35-9098-8111d5a7a3c8', '150f78d3-019b-40c0-962e-a83576309ea5', 2, 'A Ferida Aberta', NULL, '{"intro": "A vulnerabilidade \u00e9 a porta de entrada para a gra\u00e7a.", "prayer": "Mostre a Ele o seu cora\u00e7\u00e3o partido.", "practice": "N\u00e3o esconda a sua tristeza hoje; sinta-a diante dEle.", "reflection": "\u00c9 pela rachadura no cora\u00e7\u00e3o que a luz entra.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando proteger com tanto esfor\u00e7o?"}'), ('707485e8-6dc0-4b5e-9dc4-f69cf221bcf0', '150f78d3-019b-40c0-962e-a83576309ea5', 3, 'A Pureza da Intenção', NULL, '{"intro": "Muitas vezes fazemos coisas boas por motivos ego\u00edstas.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o puro e reto.", "practice": "Escolha uma tarefa e a realize com a inten\u00e7\u00e3o de agradar a Deus.", "reflection": "Faze o que fazes, por amor e s\u00f3 por amor.", "journal_prompt": "Por que voc\u00ea faz o que faz?"}'), ('b8cf5df7-c0a4-43ad-b4f3-6e93e7a839a2', '150f78d3-019b-40c0-962e-a83576309ea5', 4, 'O Coração que Escuta', NULL, '{"intro": "Escutar \u00e9 a forma mais profunda de amar.", "prayer": "Escute o sil\u00eancio de Deus no seu peito.", "practice": "Escute algu\u00e9m hoje sem interromper, sem julgar.", "reflection": "O amor tem ouvidos que a raz\u00e3o desconhece.", "journal_prompt": "Voc\u00ea est\u00e1 realmente ouvindo ou apenas esperando sua vez de falar?"}'), ('f19f7093-d270-46d1-9ce8-7a088991e5d3', '150f78d3-019b-40c0-962e-a83576309ea5', 5, 'A Fortaleza Mansa', NULL, '{"intro": "A mansid\u00e3o \u00e9 o dom\u00ednio total das pr\u00f3prias paix\u00f5es.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o manso e humilde.", "practice": "Responda com do\u00e7ura a uma provoca\u00e7\u00e3o hoje.", "reflection": "A verdadeira for\u00e7a n\u00e3o \u00e9 a que grita, \u00e9 a que sustenta.", "journal_prompt": "A sua for\u00e7a vem do medo ou da paz?"}'), ('16373f39-c20d-4ca5-97e1-f294dcc349d4', '150f78d3-019b-40c0-962e-a83576309ea5', 6, 'A Alegria Profunda', NULL, '{"intro": "A alegria crist\u00e3 \u00e9 uma decis\u00e3o, n\u00e3o um sentimento passageiro.", "prayer": "Agrade\u00e7a por 5 pequenas alegrias do dia.", "practice": "Sorria para tr\u00eas estranhos hoje.", "reflection": "Um cora\u00e7\u00e3o triste \u00e9 um alvo f\u00e1cil para o mal.", "journal_prompt": "Onde voc\u00ea busca a sua alegria?"}'), ('bb058649-ab7c-4216-9203-7cb95d316bc4', '150f78d3-019b-40c0-962e-a83576309ea5', 7, 'A Morada do Amado', NULL, '{"intro": "Toda busca humana \u00e9, no fundo, uma busca pelo Lar.", "prayer": "Descanse na presen\u00e7a dEle dentro de voc\u00ea.", "practice": "Sinta o seu cora\u00e7\u00e3o como um templo sagrado.", "reflection": "O cora\u00e7\u00e3o \u00e9 um abismo que s\u00f3 o Infinito pode preencher.", "journal_prompt": "Voc\u00ea j\u00e1 se sentiu em casa?"}'), ('39102329-9633-4eea-8b4e-3e3da8ec8815', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 1, 'A Rocha e a Areia', NULL, '{"intro": "Fundamentos invis\u00edveis sustentam estruturas vis\u00edveis.", "prayer": "Pe\u00e7a para construir sua vida sobre o que \u00e9 eterno.", "practice": "Analise em que base sua seguran\u00e7a hoje se apoia.", "reflection": "Onde voc\u00ea est\u00e1 construindo a sua casa?", "journal_prompt": "Se tudo desabasse, o que sobraria de voc\u00ea?"}'), ('8399a510-c51a-426e-ac6a-386a50ce893e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 2, 'A Revelação do Sentido', NULL, '{"intro": "A busca por sentido \u00e9 a necessidade mais profunda da alma.", "prayer": "Contemple a cria\u00e7\u00e3o e veja nela um recado para voc\u00ea.", "practice": "Observe a beleza de algo simples ao seu redor.", "reflection": "A vida n\u00e3o \u00e9 um acaso, \u00e9 um chamado.", "journal_prompt": "O que a vida est\u00e1 pedindo de voc\u00ea agora?"}'), ('455223dc-ebfb-4b93-99f2-c5835037f4e4', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 3, 'O Mistério da Encarnação', NULL, '{"intro": "A realidade material \u00e9 sagrada e cheia de presen\u00e7a.", "prayer": "Agrade\u00e7a pela sua humanidade limitada.", "practice": "Toque a terra, sinta o seu corpo, habite o presente.", "reflection": "Deus se fez carne para que a carne se tornasse divina.", "journal_prompt": "Voc\u00ea aceita as limita\u00e7\u00f5es da sua pr\u00f3pria carne?"}'), ('6ed33434-274a-4020-bca3-3a10bf234d08', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 4, 'A Lei do Amor', NULL, '{"intro": "A lei sem amor \u00e9 escravid\u00e3o; o amor sem lei \u00e9 caos.", "prayer": "Pe\u00e7a para ver o outro como Ele o v\u00ea.", "practice": "Aja hoje motivado apenas pelo amor, n\u00e3o pelo dever.", "reflection": "N\u00e3o existem regras, existe uma Pessoa a quem amamos.", "journal_prompt": "O que move as suas a\u00e7\u00f5es: o medo ou o amor?"}'), ('859fc2d1-0d9f-4e12-a9ab-6f16e22a36a1', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 5, 'A Comunhão dos Santos', NULL, '{"intro": "A solid\u00e3o \u00e9 um mito; estamos todos interconectados.", "prayer": "Sinta a companhia daqueles que j\u00e1 venceram.", "practice": "Lembre-se de algu\u00e9m que te inspira e siga seu exemplo.", "reflection": "Ningu\u00e9m caminha sozinho para o alto.", "journal_prompt": "Quem caminha com voc\u00ea no seu cora\u00e7\u00e3o?"}'), ('e9f5a167-6858-4495-b2b1-c9c96c462582', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 6, 'A Cruz como Portal', NULL, '{"intro": "A aceita\u00e7\u00e3o da dor \u00e9 a chave para a verdadeira paz.", "prayer": "Ofere\u00e7a sua dor como um gesto de amor.", "practice": "N\u00e3o reclame de um pequeno desconforto hoje.", "reflection": "O sofrimento n\u00e3o \u00e9 um beco sem sa\u00edda, \u00e9 uma passagem.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando evitar a qualquer custo?"}'), ('9812a6fd-f7c5-4b3b-b44e-97aa508d327e', '9f444a3e-9838-48b8-ae77-0b5a6829d4fa', 7, 'A Esperança da Glória', NULL, '{"intro": "A esperan\u00e7a nos permite viver o futuro no presente.", "prayer": "Descanse na promessa de que tudo ficar\u00e1 bem.", "practice": "Olhe para o horizonte e sorria para o amanh\u00e3.", "reflection": "O fim da jornada \u00e9 apenas o verdadeiro come\u00e7o.", "journal_prompt": "Pelo que voc\u00ea est\u00e1 esperando?"}'), ('998b1157-ad77-4a35-a53b-7b6cb6fa67fc', 'a1a1a1a1-3030-4000-8000-000000000001', 1, 'Dia 1 — Inquietação', 'Semana 1: Despertar', '{"pch": "Antes de te formar no ventre\u2026 Eu j\u00e1 te conhecia. Voc\u00ea n\u00e3o \u00e9 acidente \u2014 \u00e9 projeto.", "verse": "Jr 1,5", "lectio": "Leia Jr 1,4-10 lentamente. Perceba que Deus fala antes de voc\u00ea agir.", "practice": "Escreva 3 coisas que te fazem sentir vivo.", "question": "O que te inquieta quando pensa no futuro?"}'), ('4c0d4e4c-d023-49e8-9015-bab9638bd850', 'a1a1a1a1-3030-4000-8000-000000000001', 2, 'Dia 2 — Escuta', 'Semana 1: Despertar', '{"pch": "Fala, Senhor\u2026 seu servo escuta. E se a voz que voc\u00ea ignora fosse a mais importante?", "verse": "1Sm 3,10", "lectio": "Leia 1Sm 3,1-10. Samuel precisou aprender a reconhecer a voz.", "practice": "Fique 5 minutos em sil\u00eancio absoluto. Anote o que surgir.", "question": "Quando foi a \u00faltima vez que voc\u00ea parou para ouvir?"}'), ('5138f2ed-b82a-4c75-a2e9-c5c674905476', 'a1a1a1a1-3030-4000-8000-000000000001', 3, 'Dia 3 — Identidade', 'Semana 1: Despertar', '{"pch": "Voc\u00ea foi tecido em segredo\u2026 mas n\u00e3o por acaso. Cada detalhe seu \u00e9 intencional.", "verse": "Sl 139,13-14", "lectio": "Leia Sl 139,13-18. Deus te conhece por dentro.", "practice": "Liste 3 qualidades suas que outros j\u00e1 elogiaram.", "question": "O que voc\u00ea gosta em si mesmo que nunca valorizou?"}'), ('c8b91851-b773-4634-b175-606f16a1bdd4', 'a1a1a1a1-3030-4000-8000-000000000001', 4, 'Dia 4 — Dons', 'Semana 1: Despertar', '{"pch": "A cada um \u00e9 dada uma manifesta\u00e7\u00e3o do Esp\u00edrito\u2026 para o bem de todos. Seus dons n\u00e3o s\u00e3o para voc\u00ea.", "verse": "1Cor 12,7", "lectio": "Leia 1Cor 12,4-11. Cada dom \u00e9 \u00fanico e necess\u00e1rio.", "practice": "Pergunte a 2 pessoas pr\u00f3ximas: qual meu maior talento?", "question": "O que voc\u00ea faz com facilidade que outros acham dif\u00edcil?"}'), ('68da5888-cdf5-4fff-a61b-c6564471e6b6', 'a1a1a1a1-3030-4000-8000-000000000001', 5, 'Dia 5 — Sonhos', 'Semana 1: Despertar', '{"pch": "Ele pode fazer infinitamente mais\u2026 do que pedimos ou imaginamos. Seus sonhos s\u00e3o pequenos demais.", "verse": "Ef 3,20", "lectio": "Leia Ef 3,14-21. A ora\u00e7\u00e3o de Paulo \u00e9 um convite \u00e0 grandeza.", "practice": "Escreva seu maior sonho sem censura.", "question": "Se n\u00e3o houvesse limites, o que voc\u00ea faria?"}'), ('2c6ea5f0-16c1-4157-9983-0e671662dc7d', 'a1a1a1a1-3030-4000-8000-000000000001', 6, 'Dia 6 — Medo', 'Semana 1: Despertar', '{"pch": "N\u00e3o temas, pois estou contigo\u2026 O medo \u00e9 real, mas n\u00e3o \u00e9 verdadeiro.", "verse": "Is 41,10", "lectio": "Leia Is 41,8-13. Deus segura sua m\u00e3o direita.", "practice": "Nomeie seu maior medo. Depois, entregue-o em ora\u00e7\u00e3o.", "question": "Qual medo te impede de avan\u00e7ar?"}'), ('4fe490ab-b93c-4111-903e-f6594093c2ec', 'a1a1a1a1-3030-4000-8000-000000000001', 7, 'Dia 7 — Entrega', 'Semana 1: Despertar', '{"pch": "Confia ao Senhor as tuas obras\u2026 e os teus planos ser\u00e3o estabelecidos. Solte o controle.", "verse": "Pv 16,3", "lectio": "Leia Pv 16,1-9. O cora\u00e7\u00e3o planeja, mas Deus dirige.", "practice": "Fa\u00e7a uma ora\u00e7\u00e3o de entrega: Senhor, minha vida \u00e9 tua.", "question": "O que voc\u00ea precisa entregar a Deus hoje?"}'), ('bb057ba9-b3be-4549-b096-7d10af160978', 'a1a1a1a1-3030-4000-8000-000000000001', 8, 'Dia 8 — Raízes', 'Semana 2: Desconstruir', '{"pch": "Toda \u00e1rvore boa d\u00e1 bons frutos\u2026 Antes de mudar os frutos, examine as ra\u00edzes.", "verse": "Mt 7,17", "lectio": "Leia Mt 7,15-20. Os frutos revelam a raiz.", "practice": "Escreva 3 cren\u00e7as negativas que carrega desde a inf\u00e2ncia.", "question": "Que cren\u00e7as sobre voc\u00ea mesmo te limitam?"}'), ('d43f46b7-ab47-4b02-9524-be185e2f09b4', 'a1a1a1a1-3030-4000-8000-000000000001', 9, 'Dia 9 — Comparação', 'Semana 2: Desconstruir', '{"pch": "Cada um examine a pr\u00f3pria obra\u2026 sem se comparar. Sua corrida \u00e9 s\u00f3 sua.", "verse": "Gl 6,4", "lectio": "Leia Gl 6,1-5. Cada um carregar\u00e1 seu pr\u00f3prio fardo.", "practice": "Desative as redes sociais por 24h. Observe como se sente.", "question": "Com quem voc\u00ea se compara? E por qu\u00ea?"}'), ('5d957e20-f7a8-4aac-b2ce-962d35426dba', 'a1a1a1a1-3030-4000-8000-000000000001', 10, 'Dia 10 — Expectativas', 'Semana 2: Desconstruir', '{"pch": "N\u00e3o se conformem\u2026 Transformem-se. As expectativas dos outros n\u00e3o s\u00e3o o plano de Deus para voc\u00ea.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-8. Renovar a mente \u00e9 o caminho.", "practice": "Escreva: o que EU quero vs. o que ESPERAM de mim.", "question": "Que expectativa alheia voc\u00ea carrega como sua?"}'), ('d805edc0-7835-436f-8dca-41e06e9b3b45', 'a1a1a1a1-3030-4000-8000-000000000001', 11, 'Dia 11 — Feridas', 'Semana 2: Desconstruir', '{"pch": "Minha gra\u00e7a te basta\u2026 A for\u00e7a se aperfei\u00e7oa na fraqueza. Suas feridas t\u00eam prop\u00f3sito.", "verse": "2Cor 12,9", "lectio": "Leia 2Cor 12,7-10. Paulo encontrou for\u00e7a na fraqueza.", "practice": "Escreva uma carta de perd\u00e3o a si mesmo.", "question": "Que dor do passado ainda influencia suas decis\u00f5es?"}'), ('eb92ec35-11e0-4f15-adeb-e8b806751a75', 'a1a1a1a1-3030-4000-8000-000000000001', 12, 'Dia 12 — Desapego', 'Semana 2: Desconstruir', '{"pch": "Esquecendo-me do que fica para tr\u00e1s\u2026 avan\u00e7ando para o que est\u00e1 adiante. Solte o passado.", "verse": "Fl 3,13", "lectio": "Leia Fl 3,12-16. Paulo corria para frente.", "practice": "Escolha algo simb\u00f3lico para soltar hoje \u2014 um objeto, uma mem\u00f3ria, um ressentimento.", "question": "O que do passado voc\u00ea precisa largar para avan\u00e7ar?"}'), ('b5e69546-2d9f-4b03-9a62-224c77defd11', 'a1a1a1a1-3030-4000-8000-000000000001', 13, 'Dia 13 — Perdão', 'Semana 2: Desconstruir', '{"pch": "Perdoem como o Senhor perdoou voc\u00eas\u2026 O perd\u00e3o n\u00e3o \u00e9 sentimento \u2014 \u00e9 decis\u00e3o.", "verse": "Cl 3,13", "lectio": "Leia Cl 3,12-17. Revestir-se de compaix\u00e3o.", "practice": "Escreva o nome de quem precisa perdoar. Reze por essa pessoa.", "question": "Quem voc\u00ea ainda n\u00e3o perdoou?"}'), ('a33cfda2-79e6-40b2-b690-0c22e1890abb', 'a1a1a1a1-3030-4000-8000-000000000001', 14, 'Dia 14 — Silêncio', 'Semana 2: Desconstruir', '{"pch": "Aquietai-vos e sabei que Eu sou Deus\u2026 No barulho, voc\u00ea se perde. No sil\u00eancio, se encontra.", "verse": "Sl 46,10", "lectio": "Leia Sl 46. Deus \u00e9 ref\u00fagio no meio do caos.", "practice": "10 minutos de sil\u00eancio contemplativo antes de dormir.", "question": "O que o barulho da sua rotina esconde?"}'), ('3c7aeb85-1858-467c-975d-a666e9d8ebd0', 'a1a1a1a1-3030-4000-8000-000000000001', 15, 'Dia 15 — Visão', 'Semana 3: Reconstruir', '{"pch": "Escreve a vis\u00e3o\u2026 e torna-a clara. O que n\u00e3o est\u00e1 escrito, n\u00e3o se realiza.", "verse": "Hc 2,2", "lectio": "Leia Hc 2,1-4. A vis\u00e3o tem tempo certo.", "practice": "Escreva sua vis\u00e3o de vida em 1 par\u00e1grafo.", "question": "Qual sua vis\u00e3o para os pr\u00f3ximos 5 anos?"}'), ('12e661ac-582e-4c7b-8899-2ac42118bf80', 'a1a1a1a1-3030-4000-8000-000000000001', 16, 'Dia 16 — Valores', 'Semana 3: Reconstruir', '{"pch": "Onde est\u00e1 o teu tesouro\u2026 a\u00ed est\u00e1 o teu cora\u00e7\u00e3o. O que voc\u00ea valoriza define quem voc\u00ea \u00e9.", "verse": "Mt 6,21", "lectio": "Leia Mt 6,19-24. Tesouro no c\u00e9u vs. tesouro na terra.", "practice": "Liste seus 5 valores mais importantes. Veja se sua vida reflete isso.", "question": "Quais s\u00e3o seus 3 valores inegoci\u00e1veis?"}'), ('2e987379-972e-47a4-bcb1-a2ecad2d45c5', 'a1a1a1a1-3030-4000-8000-000000000001', 17, 'Dia 17 — Decisão', 'Semana 3: Reconstruir', '{"pch": "Escolhei hoje a quem servireis\u2026 A indecis\u00e3o tamb\u00e9m \u00e9 uma escolha.", "verse": "Js 24,15", "lectio": "Leia Js 24,14-18. Josu\u00e9 decidiu por toda sua casa.", "practice": "Tome uma decis\u00e3o que est\u00e1 pendente. Qualquer uma. Agora.", "question": "Que decis\u00e3o voc\u00ea est\u00e1 adiando?"}'), ('7c61db8f-303e-4621-83e3-09bac050ac36', 'a1a1a1a1-3030-4000-8000-000000000001', 18, 'Dia 18 — Disciplina', 'Semana 3: Reconstruir', '{"pch": "Disciplino o meu corpo\u2026 Sem disciplina, o prop\u00f3sito vira apenas desejo.", "verse": "1Cor 9,27", "lectio": "Leia 1Cor 9,24-27. Paulo corria para vencer.", "practice": "Escolha 1 h\u00e1bito pequeno e pratique por 7 dias consecutivos.", "question": "Em que \u00e1rea da sua vida falta disciplina?"}'), ('b1976d29-1635-4597-a295-21fb26c1cdcb', 'a1a1a1a1-3030-4000-8000-000000000001', 19, 'Dia 19 — Coragem', 'Semana 3: Reconstruir', '{"pch": "S\u00ea forte e corajoso\u2026 porque o Senhor est\u00e1 contigo. Coragem n\u00e3o \u00e9 aus\u00eancia de medo.", "verse": "Js 1,9", "lectio": "Leia Js 1,1-9. Deus repetiu: s\u00ea forte.", "practice": "Fa\u00e7a uma coisa que te assusta hoje \u2014 mesmo pequena.", "question": "O que voc\u00ea faria se n\u00e3o tivesse medo?"}'), ('bb65465d-4947-48f6-9d6c-a18dbca31406', 'a1a1a1a1-3030-4000-8000-000000000001', 20, 'Dia 20 — Serviço', 'Semana 3: Reconstruir', '{"pch": "O Filho do Homem veio para servir\u2026 Prop\u00f3sito n\u00e3o \u00e9 sobre voc\u00ea \u2014 \u00e9 sobre quem voc\u00ea serve.", "verse": "Mc 10,45", "lectio": "Leia Mc 10,42-45. A lideran\u00e7a \u00e9 servi\u00e7o.", "practice": "Fa\u00e7a algo por algu\u00e9m hoje sem esperar nada em troca.", "question": "Quem se beneficia quando voc\u00ea vive seu melhor?"}'), ('282a548d-3009-4cf5-aa5d-0f01aa82aac2', 'a1a1a1a1-3030-4000-8000-000000000001', 21, 'Dia 21 — Identidade em Cristo', 'Semana 3: Reconstruir', '{"pch": "Se algu\u00e9m est\u00e1 em Cristo\u2026 \u00e9 nova criatura. Sua identidade n\u00e3o est\u00e1 no que voc\u00ea faz, mas em quem voc\u00ea \u00e9.", "verse": "2Cor 5,17", "lectio": "Leia 2Cor 5,14-21. Embaixadores de Cristo.", "practice": "Escreva: Eu sou ______ em Cristo. Complete 5 vezes.", "question": "Quem voc\u00ea \u00e9 quando ningu\u00e9m est\u00e1 vendo?"}'), ('6f54e6e9-2b46-44e2-aca6-1efbebe2d0e3', 'a1a1a1a1-3030-4000-8000-000000000001', 22, 'Dia 22 — Presença', 'Semana 4: Integrar', '{"pch": "Na tua presen\u00e7a h\u00e1 plenitude de alegria\u2026 Prop\u00f3sito come\u00e7a quando voc\u00ea est\u00e1 presente.", "verse": "Sl 16,11", "lectio": "Leia Sl 16. Deus \u00e9 a por\u00e7\u00e3o da heran\u00e7a.", "practice": "Viva hoje com aten\u00e7\u00e3o plena. Observe cada momento.", "question": "Em que momentos voc\u00ea se sente mais presente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;